// 1. 饿汉式：类加载即创建，JVM 通过 <clinit> 锁保证只建一次
public class SingletonHungry {
    private static final SingletonHungry INSTANCE = new SingletonHungry();
    private SingletonHungry() {}
    public static SingletonHungry getInstance() { return INSTANCE; }
}

// 2. 懒汉式（线程不安全，反例）：双线程同时进 if 会各 new 一个
public class SingletonLazyUnsafe {
    private static SingletonLazyUnsafe instance;
    private SingletonLazyUnsafe() {}
    public static SingletonLazyUnsafe getInstance() {
        if (instance == null) {
            instance = new SingletonLazyUnsafe();
        }
        return instance;
    }
}

// 3. 双重检查锁 DCL：volatile 防止 new 的三步指令重排
public class SingletonDCL {
    private static volatile SingletonDCL instance;  // volatile 关键
    private SingletonDCL() {}
    public static SingletonDCL getInstance() {
        if (instance == null) {                       // 第一次判空，无锁快速返回
            synchronized (SingletonDCL.class) {
                if (instance == null) {               // 第二次判空，防重复创建
                    instance = new SingletonDCL();    // 分配内存 -> <init> -> 赋引用
                }
            }
        }
        return instance;
    }
}

// 4. 静态内部类 Holder：第一次访问 Holder.INSTANCE 才触发加载，懒加载且无锁
public class SingletonInner {
    private SingletonInner() {}
    private static class Holder {
        private static final SingletonInner INSTANCE = new SingletonInner();
    }
    public static SingletonInner getInstance() { return Holder.INSTANCE; }
}

// 5. 枚举：天然防反射（Constructor.newInstance 对枚举抛 IllegalArgumentException）
//        天然防序列化（按枚举名查表，不走构造）
public enum SingletonEnum {
    INSTANCE;
    public void doSomething() { /* 业务方法 */ }
}

// 6. 普通单例防序列化破坏：必须加 readResolve，否则反序列化会绕过构造造新对象
public class SingletonSerializable implements java.io.Serializable {
    private static final SingletonSerializable INSTANCE = new SingletonSerializable();
    private SingletonSerializable() {}
    public static SingletonSerializable getInstance() { return INSTANCE; }
    private Object readResolve() { return INSTANCE; }   // 反序列化最后一步替换返回值
}
